arguments.content:
:root {
  --primary: #0066FF;
  --primary-hover: #0052CC;
  --primary-light: #EFF6FF;
  --accent: #059669;
  --accent-hover: #047857;
  --text-main: #111827;
  --text-muted: #4B5563;
  --text-light: #6B7280;
  --bg-page: #FFFFFF;
  --bg-section: #F9FAFB;
  --border-light: #E5E7EB;
  --border-focus: #93C5FD;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --container: 1200px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  color: var(--text-main);
  background-color: var(--bg-page);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary-hover);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); color: var(--text-main); margin-bottom: 1.5rem; }
h2 { font-size: clamp(2rem, 4vw, 2.5rem); margin-bottom: 1rem; }
h3 { font-size: 1.25rem; margin-bottom: 0.5rem; }
p { font-size: 1rem; color: var(--text-muted); }
.lead { font-size: clamp(1.125rem, 2vw, 1.25rem); color: var(--text-muted); margin-bottom: 2.5rem; max-width: 800px; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  transition: all 0.2s ease;
  gap: 0.5rem;
}

.btn-primary {
  background-color: var(--accent);
  color: white;
}
.btn-primary:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
  color: white;
}

.btn-secondary {
  background-color: var(--primary-light);
  color: var(--primary);
}
.btn-secondary:hover {
  background-color: #DBEAFE;
  color: var(--primary-hover);
}

.btn-outline {
  border: 1.5px solid var(--border-light);
  color: var(--text-main);
}
.btn-outline:hover {
  border-color: var(--text-light);
  background-color: var(--bg-section);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border-light);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4.5rem;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.logo i {
  color: var(--accent);
  font-size: 1.75rem;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-desktop a {
  color: var(--text-main);
  font-weight: 500;
}
.nav-desktop a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.mobile-toggle {
  display: none;
  font-size: 1.5rem;
  color: var(--text-main);
}

/* Mobile Menu */
.mobile-menu {
  position: fixed;
  top: 4.5rem;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: white;
  z-index: 40;
  padding: 2rem 1.5rem;
  transform: translateX(100%);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-menu.active {
  transform: translateX(0);
}
.mobile-menu a {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-main);
}

/* Hero Section */
.hero {
  padding: 6rem 0 4rem;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-page) 0%, var(--primary-light) 100%);
  position: relative;
  overflow: hidden;
}

.hero-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  z-index: 2;
}

/* Search Box */
.search-container {
  background: white;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-xl);
  padding: 0.5rem;
  display: flex;
  align-items: center;
  max-width: 900px;
  width: 100%;
  margin: 0 auto 3rem;
  position: relative;
  border: 1px solid var(--border-light);
}

.search-field {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 0.5rem 1.5rem;
  border-right: 1px solid var(--border-light);
  position: relative;
  text-align: left;
}

.search-field:last-of-type {
  border-right: none;
}

.search-field label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.search-input-wrapper {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.search-input-wrapper i {
  color: var(--text-light);
  font-size: 1.25rem;
}

.search-field input,
.search-field select {
  width: 100%;
  border: none;
  background: transparent;
  font-size: 1rem;
  color: var(--text-main);
  outline: none;
  font-family: inherit;
  padding: 0;
  appearance: none;
  cursor: pointer;
}

.search-field input::placeholder {
  color: var(--text-light);
}

.search-submit {
  background-color: var(--primary);
  color: white;
  height: 3.5rem;
  padding: 0 2rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
  margin-left: 0.5rem;
}
.search-submit:hover {
  background-color: var(--primary-hover);
}

/* Autocomplete Dropdown */
.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 1rem);
  left: 0;
  width: 100%;
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--border-light);
  z-index: 10;
  display: none;
  overflow: hidden;
  text-align: left;
}
.autocomplete-dropdown.active {
  display: block;
}
.autocomplete-item {
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  border-bottom: 1px solid var(--border-light);
}
.autocomplete-item:last-child {
  border-bottom: none;
}
.autocomplete-item:hover {
  background-color: var(--bg-section);
}
.autocomplete-item i {
  color: var(--text-light);
  background: var(--bg-section);
  padding: 0.5rem;
  border-radius: var(--radius-md);
}

/* Stats */
.stats {
  background: white;
  padding: 3rem 0;
  border-top: 1px solid var(--border-light);
  border-bottom: 1px solid var(--border-light);
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}
.stat-item {
  padding: 1rem;
}
.stat-value {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 0.5rem;
  line-height: 1;
}
.stat-label {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-muted);
}

/* Specialties */
.section {
  padding: 5rem 0;
}
.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.specialty-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
}

.specialty-card {
  background: white;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: all 0.2s ease;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
}
.specialty-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--border-focus);
}
.specialty-icon {
  width: 3.5rem;
  height: 3.5rem;
  background: var(--primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--primary);
}
.specialty-info h3 {
  margin: 0 0 0.25rem 0;
  color: var(--text-main);
}
.specialty-info p {
  font-size: 0.875rem;
  margin: 0;
}

/* How It Works */
.bg-gray {
  background-color: var(--bg-section);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  text-align: center;
  position: relative;
}

.step-card {
  background: white;
  padding: 2.5rem 1.5rem;
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
  position: relative;
  z-index: 2;
}

.step-number {
  width: 4rem;
  height: 4rem;
  background: var(--accent);
  color: white;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  margin: -4.5rem auto 1.5rem;
  border: 4px solid white;
}

.step-card h3 {
  margin-bottom: 1rem;
}

/* Testimonials */
.testimonial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.testimonial-card {
  background: white;
  padding: 2rem;
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
}

.stars {
  color: #F59E0B;
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.testimonial-quote {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 3rem;
  height: 3rem;
  background: var(--primary-light);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  font-weight: 700;
}

/* Mobile App Promo */
.app-promo {
  background: var(--primary);
  border-radius: var(--radius-xl);
  padding: 4rem;
  color: white;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.app-promo h2 {
  color: white;
}

.app-promo p {
  color: rgba(255, 255, 255, 0.9);
}

.app-features {
  margin: 2rem 0;
}
.app-features li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
  font-size: 1.125rem;
}

.app-features i {
  color: var(--accent);
  background: white;
  border-radius: var(--radius-full);
  padding: 0.25rem;
}

.store-buttons {
  display: flex;
  gap: 1rem;
}

.app-mockup {
  position: absolute;
  right: -5%;
  bottom: -20%;
  width: 50%;
  height: 120%;
  background: rgba(255,255,255,0.1);
  border-radius: 3rem;
  border: 8px solid rgba(255,255,255,0.2);
  transform: rotate(-15deg);
  box-shadow: var(--shadow-xl);
}

/* Footer */
.footer {
  background: white;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border-light);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 4rem;
}

.footer-brand p {
  margin-top: 1rem;
  max-width: 300px;
}

.footer h4 {
  color: var(--text-main);
  font-size: 1rem;
  margin-bottom: 1.5rem;
}

.footer ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer a {
  color: var(--text-muted);
}
.footer a:hover {
  color: var(--primary);
}

.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-light);
  color: var(--text-light);
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 992px) {
  .search-container {
    flex-direction: column;
    border-radius: var(--radius-lg);
    padding: 1.5rem;
    gap: 1rem;
  }
  .search-field {
    border-right: none;
    border-bottom: 1px solid var(--border-light);
    padding: 0.5rem 0 1rem;
    width: 100%;
  }
  .search-field:last-of-type {
    border-bottom: none;
  }
  .search-submit {
    width: 100%;
    justify-content: center;
    margin-left: 0;
    margin-top: 1rem;
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .steps-grid {
    grid-template-columns: 1fr;
    gap: 4rem;
  }
  .app-promo {
    grid-template-columns: 1fr;
    padding: 3rem 2rem;
    text-align: center;
  }
  .app-features li {
    justify-content: center;
  }
  .store-buttons {
    justify-content: center;
  }
  .app-mockup {
    display: none;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-desktop, .nav-actions {
    display: none;
  }
  .mobile-toggle {
    display: block;
  }
  .stats-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileToggle = document.getElementById('mobile-toggle');
  const mobileMenu = document.getElementById('mobile-menu');

  if (mobileToggle && mobileMenu) {
    mobileToggle.addEventListener('click', () => {
      mobileMenu.classList.toggle('active');
      const icon = mobileToggle.querySelector('i');
      if (mobileMenu.classList.contains('active')) {
        icon.classList.remove('ri-menu-line');
        icon.classList.add('ri-close-line');
      } else {
        icon.classList.remove('ri-close-line');
        icon.classList.add('ri-menu-line');
      }
    });
  }

  // Autocomplete functionality
  const searchInput = document.getElementById('specialty-search');
  const autocompleteDropdown = document.getElementById('autocomplete-dropdown');
  const searchForm = document.getElementById('main-search-form');

  if (searchInput && autocompleteDropdown) {
    const suggestions = [
      { text: 'Dentist', icon: 'ri-tooth-line' },
      { text: 'Primary Care', icon: 'ri-stethoscope-line' },
      { text: 'Dermatologist', icon: 'ri-magic-line' },
      { text: 'Back pain', icon: 'ri-body-scan-line' },
      { text: 'Dr. Sarah Chen', icon: 'ri-user-smile-line' }
    ];

    searchInput.addEventListener('input', (e) => {
      const value = e.target.value.toLowerCase();
      autocompleteDropdown.innerHTML = '';

      if (value.length > 0) {
        const filtered = suggestions.filter(s => s.text.toLowerCase().includes(value));

        if (filtered.length > 0) {
          filtered.forEach(item => {
            const div = document.createElement('div');
            div.className = 'autocomplete-item';
            div.innerHTML = `<i class="${item.icon}"></i><span>${item.text}</span>`;
            div.addEventListener('click', () => {
              searchInput.value = item.text;
              autocompleteDropdown.classList.remove('active');
            });
            autocompleteDropdown.appendChild(div);
          });
          autocompleteDropdown.classList.add('active');
        } else {
          autocompleteDropdown.classList.remove('active');
        }
      } else {
        autocompleteDropdown.classList.remove('active');
      }
    });

    // Close dropdown on click outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-field')) {
        autocompleteDropdown.classList.remove('active');
      }
    });
  }

  if (searchForm) {
    searchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Navigation interaction mock
      console.log('Search submitted');
      window.location.href = '#search-results';
    });
  }

  // Specialty Cards interaction
  const specialtyCards = document.querySelectorAll('.specialty-card');
  specialtyCards.forEach(card => {
    card.addEventListener('click', () => {
      // Navigation interaction mock
      console.log('Navigating to filtered search results for:', card.querySelector('h3').innerText);
      window.location.href = '#search-results';
    });
  });
});
